public class Main {
    static int search(int[] sorted, int target, int low, int high) {
        if (low > high) {
            return -1;
        }
        int mid = (low + high) / 2;
        if (sorted[mid] == target) {
            return mid;
        } else if (sorted[mid] < target) {
            return search(sorted, target, mid + 1, high);
        } else {
            return search(sorted, target, low, mid - 1);
        }
    }

    public static void main(String[] args) {
        int[] nums = {3, 8, 12, 19, 25, 31, 40};
        int index = search(nums, 25, 0, nums.length - 1);
        System.out.println("Found 25 at index " + index);
    }
}
